## Part 1: Playground → permanent test instances

Create `tests/church.rs`. The pattern: **helpers at the top, experiments as named tests**:

```rust
//! Church encodings: experiments that graduated into regression tests.

use axolotl::kernel::*;

// ----- helpers -----

fn zero() -> TermRef {
    lam(lam(var(0))) // fn(f) { fn(x) { x } }
}

fn succ(n: TermRef) -> TermRef {
    // fn(f) { fn(x) { f(n(f)(x)) } }  — the hard part is getting the indices right;
    // work it out on paper: under 2 binders, n is Var(2), f is Var(1), x is Var(0)
    lam(lam(app(var(1), app(app(var(2), var(1)), var(0))))))
}

fn church(n: u64) -> TermRef {
    // Rust recursion building lambda-calculus recursion
    match n {
        0 => zero(),
        _ => succ(church(n - 1)),
    }
}

fn plus(m: TermRef, n: TermRef) -> TermRef {
    // fn(f) { fn(x) { m(f)(n(f)(x)) } }
    lam(lam(app(
        app(var(3), var(1)),
        app(app(var(2), var(1)), var(0)),
    )))
}

// ----- the capstone -----

#[test]
fn two_plus_two_is_four() {
    assert_eq!(
        normalize(&app(app(plus(church(2)), church(2)), ... )),
        // hmm — careful: plus takes m then n; build the call yourself
    );
}
```

